15	/**
16	 * <p>Client -&gt; server: the player chose, from the "Bind to staff" button in the Spellbook, which
17	 * spell to assign to the staff held in their main hand. Rewrites the {@code quickSpell} of THAT
18	 * item instead of creating a new one (see {@code SpellCommand.buildStaffStack}), so the same staff
19	 * can be reassigned as many times as needed — with hundreds of spells, a distinct staff item per
20	 * spell isn't viable.</p>
21	 *
22	 * <p>Only acts if the item in hand already has {@code staffConfigurable:true}: a player with a
23	 * modified client can't turn an arbitrary item into a staff by hand-crafting this message.</p>
24	 */
25	public class StaffBindMessage {
26		String spellId;
27	
28		public StaffBindMessage(String spellId) {
29			this.spellId = spellId;
30		}
31	
32		public StaffBindMessage(FriendlyByteBuf buffer) {
33			this.spellId = buffer.readUtf();
34		}
35	
36		public static void buffer(StaffBindMessage message, FriendlyByteBuf buffer) {
37			buffer.writeUtf(message.spellId);
38		}
