40		public static void handler(StaffBindMessage message, Supplier<NetworkEvent.Context> contextSupplier) {
41			NetworkEvent.Context context = contextSupplier.get();
42			NetworkUtil.handleOnServer(context, () -> {
43				ServerPlayer player = context.getSender();
44				if (player == null) return;
45	
46				SpellRegistry.Spell spell = SpellRegistry.get(message.spellId);
47				if (spell == null) return;
48	
49				ItemStack stack = player.getMainHandItem();
50				if (!SpellRegistry.bindStaff(stack, message.spellId)) return;
51	
52				stack.setHoverName(Component.translatable("chat.dndsheets.staff.item_name", ContentNames.of(spell.name())));
53				player.sendSystemMessage(Component.translatable("chat.dndsheets.staff.bound", ContentNames.of(spell.name())).withStyle(ChatFormatting.GREEN));
54			});
55		}
56	}
