136		public static ItemStack buildStaffStack(String spellId, SpellRegistry.Spell spell, String itemId) {
137			//null = "the mod's own staff". Requested by the three call sites that used to pass a blaze rod by hand.
138			ResourceLocation itemLoc = itemId == null ? null : ResourceLocation.tryParse(itemId);
139			Item baseItem = itemLoc != null ? ForgeRegistries.ITEMS.getValue(itemLoc) : null;
140			//With no item configured, the mod's own staff with its texture. With one configured, whatever the
141			//DM says: whoever sets "minecraft:trident" wants to see a trident, not our icon on top of it.
142			boolean ownStaff = baseItem == null;
143			if (ownStaff) baseItem = net.hawthorn.dndsheets.init.DndsheetsModItems.TOKEN.get();
144	
145			ItemStack stack = new ItemStack(baseItem);
146			if (ownStaff) net.hawthorn.dndsheets.ItemLook.STAFF.applyTo(stack);
147			CompoundTag dndTag = new CompoundTag();
148			dndTag.putString("quickSpell", spellId);
149			dndTag.putBoolean("staffConfigurable", true);
150			stack.getOrCreateTag().put("dndsheets", dndTag);
151			//The SAME key StaffBindMessage uses when rebinding the staff in-game: it's the same object through
152			//two paths, and this used to have "Staff of " hardcoded by hand. An English client would get a
153			//staff whose name was in Spanish and which even stopped matching once it was rebound.
154			stack.setHoverName(Component.translatable("chat.dndsheets.staff.item_name", ContentNames.of(spell.name())));
155			return stack;
156		}
