7	/**
8	 * <p>Visual identity shared by the mod's "flat" screens (list panels, short forms, dialogs): a
9	 * leather-bound tome with brass corner pieces, drawn with the same beveling Minecraft's GUI uses. It's
10	 * the only place this look lives — changing it here changes it across the forty-plus screens that hang
11	 * off {@code ListPickerScreen}, {@code SmallFormScreen}, and {@code ModalDialogScreen}.</p>
12	 *
13	 * <p><b>Why beveled and not a flat border.</b> Minecraft draws its ENTIRE interface with two bevel
14	 * lines — light on top and left, dark on bottom and right — over a flat fill. That's what makes a panel
15	 * "belong" to the game instead of looking like a window pasted on top. The D&amp;D theme comes in
16	 * through color (dark leather and aged brass) and the corner pieces, not by breaking that grammar.</p>
17	 *
18	 * <p>The fill is deliberately near-opaque: the blurred world background still shows through behind it,
19	 * but without competing with the text. A translucent panel over a snowy biome leaves white text
20	 * illegible.</p>
21	 */
22	public final class GuiStyle {
23	
24		//--- Text colors ---
25		/** Parchment, not pure white: absolute white over dark leather vibrates and tires the eye.
26		 *  Public: also used by the turn HUD (client.TurnHudOverlay), outside this package. */
27		public static final int TITLE_COLOR = 0xFFE9D8B4;
28		public static final int SUBTITLE_COLOR = 0xFFB9A88C;
29		/** Public: the only GuiStyle color consumed by the dungeon toolkit addon (a separate module). */
30		public static final int MUTED_COLOR = 0xFF8C8071;
31		/** Aged brass, for things that should stand out without shouting (markers, active values). Public, see above. */
32		public static final int ACCENT_COLOR = 0xFFC9A227;
33	
34		//--- Panel colors ---
35		//The fill is a tileable leather texture (generated by tools/make_panel_texture.py, FFT pink noise:
36		//seamless by construction, average color = the old FILL_COLOR 0x1A140E) with a translucent depth
37		//gradient on top — light falls from above, matching the bevel. The texture gives the pore; the
38		//gradient, the volume; text contrast doesn't change from what was already tested, because the
39		//midtone is the same.
40		private static final ResourceLocation LEATHER = new ResourceLocation("dndsheets", "textures/screens/panel_leather.png");
41		private static final int LEATHER_TILE = 64;
42		private static final int DEPTH_TOP = 0x2EFFD9A0;    //Warm light on top, translucent.
43		private static final int DEPTH_BOTTOM = 0x66000000; //Shadow at the bottom, translucent.
44		private static final int BEVEL_LIGHT = 0xFF6B5636;  //Worn brass: light on top and left.
45		private static final int BEVEL_DARK = 0xFF0B0906;   //Shadow on bottom and right.
46		private static final int EDGE_COLOR = 0xFF2E2418;   //Outer outline, one shade over the fill.
47		private static final int STUD_COLOR = 0xFFC9A227;   //Brass corner pieces.
48	
49		private static final int STUD_SIZE = 3;
50	
51		private GuiStyle() {
52		}
53	
54		/**
55		 * <p>Background panel. The signature is unchanged from the previous version: the forty-plus screens
56		 * that call it keep working without being touched. Public: also used by the turn HUD (client.
57		 * TurnHudOverlay) so the initiative tracker has the same tome-like look as the rest of the mod
58		 * instead of an overlay that belongs to nothing.</p>
59		 */
60		public static void panel(GuiGraphics guiGraphics, int left, int top, int right, int bottom) {
61			//Outer outline first, one pixel outside the bevel: separates the panel from the blurred world
62			//behind it without needing a soft shadow, which looks dirty at Minecraft's pixel scale.
63			guiGraphics.fill(left - 1, top - 1, right + 1, bottom + 1, EDGE_COLOR);
64	
65			//Tiled leather with the same slight transparency the flat fill used to have (0xF2): the world
66			//still shows through faintly behind it without competing with the text. setColor affects the
67			//next blit and is always restored — leaving it set would tint everything the screen paints
68			//afterward. Blending is enabled by hand: blit() draws with whatever state is set (fill() manages
69			//it on its own, blit() doesn't), and without blending, setColor's alpha is silently ignored.
70			com.mojang.blaze3d.systems.RenderSystem.enableBlend();
71			com.mojang.blaze3d.systems.RenderSystem.defaultBlendFunc();
72			guiGraphics.setColor(1.0F, 1.0F, 1.0F, 0.95F);
73			for (int tileY = top; tileY < bottom; tileY += LEATHER_TILE) {
74				for (int tileX = left; tileX < right; tileX += LEATHER_TILE) {
75					int tileW = Math.min(LEATHER_TILE, right - tileX);
76					int tileH = Math.min(LEATHER_TILE, bottom - tileY);
77					guiGraphics.blit(LEATHER, tileX, tileY, 0, 0, tileW, tileH, LEATHER_TILE, LEATHER_TILE);
78				}
79			}
80			guiGraphics.setColor(1.0F, 1.0F, 1.0F, 1.0F);
81	
82			guiGraphics.fillGradient(left, top, right, bottom, DEPTH_TOP, DEPTH_BOTTOM);
83	
84			//Minecraft-style bevel: light on top/left, dark on bottom/right. Two pixels, not one — at GUI
85			//Scale 2 (the normal setting) a one-pixel bevel disappears.
86			guiGraphics.fill(left, top, right - 2, top + 2, BEVEL_LIGHT);
87			guiGraphics.fill(left, top, left + 2, bottom - 2, BEVEL_LIGHT);
88			guiGraphics.fill(left + 2, bottom - 2, right, bottom, BEVEL_DARK);
89			guiGraphics.fill(right - 2, top + 2, right, bottom, BEVEL_DARK);
90	
91			corners(guiGraphics, left, top, right, bottom);
92		}
93	
94		//Corner pieces: four brass brackets at the corners, like a bound book's. This is what gives the
95		//"tome" impression without drawing a single texture pixel or depending on a PNG.
96		private static void corners(GuiGraphics guiGraphics, int left, int top, int right, int bottom) {
97			int s = STUD_SIZE;
98			int arm = s * 3;
99	
100			//Top left.
101			guiGraphics.fill(left + 2, top + 2, left + 2 + arm, top + 2 + s, STUD_COLOR);
102			guiGraphics.fill(left + 2, top + 2, left + 2 + s, top + 2 + arm, STUD_COLOR);
103			//Top right.
104			guiGraphics.fill(right - 2 - arm, top + 2, right - 2, top + 2 + s, STUD_COLOR);
105			guiGraphics.fill(right - 2 - s, top + 2, right - 2, top + 2 + arm, STUD_COLOR);
106			//Bottom left.
107			guiGraphics.fill(left + 2, bottom - 2 - s, left + 2 + arm, bottom - 2, STUD_COLOR);
108			guiGraphics.fill(left + 2, bottom - 2 - arm, left + 2 + s, bottom - 2, STUD_COLOR);
109			//Bottom right.
110			guiGraphics.fill(right - 2 - arm, bottom - 2 - s, right - 2, bottom - 2, STUD_COLOR);
111			guiGraphics.fill(right - 2 - s, bottom - 2 - arm, right - 2, bottom - 2, STUD_COLOR);
112		}
113	
114		/** Screen titles in Cinzel (SIL OFL, see CREDITS); anything the font lacks falls back to the default one. */
115		private static final ResourceLocation TITLE_FONT = new ResourceLocation("dndsheets", "title");
116	
117		public static Component title(Component text) {
118			return text.copy().withStyle(style -> style.withFont(TITLE_FONT));
119		}
120	
121		/**
122		 * <p>Horizontal brass rule, to separate a title from its content. Public for screens that want to
123		 * mark sections without each one inventing its own line color.</p>
124		 */
125		public static void rule(GuiGraphics guiGraphics, int left, int right, int y) {
126			guiGraphics.fill(left, y, right, y + 1, BEVEL_LIGHT);
127		}
128	
129		/**
130		 * <p>The same rule with a brass diamond in the center — a D&amp;D manual's header ornament, in five
131		 * fills. For the rule under a screen's TITLE; internal separators keep using {@link #rule}, because an
132		 * ornament repeated per section stops being an ornament.</p>
133		 */
134		public static void ruleOrnate(GuiGraphics guiGraphics, int left, int right, int y) {
135			rule(guiGraphics, left, right, y);
136			int cx = (left + right) / 2;
137			guiGraphics.fill(cx - 2, y - 1, cx + 3, y + 2, BEVEL_LIGHT);
138			guiGraphics.fill(cx - 1, y - 1, cx + 2, y + 2, STUD_COLOR);
139			guiGraphics.fill(cx, y - 2, cx + 1, y + 3, STUD_COLOR);
140		}
141	}
