22	 * <p>Focus/hover state isn't marked with just a background color change: the brass rule also lights up
23	 * and the text lightens. A single-tone change on a dark background is exactly what doesn't
24	 * get distinguished at low monitor brightness.</p>
25	 */
26	public class TomeButton extends Button {
27	
28		//Dim parchment at rest, lit up on hover. Darker than the character sheet: it's
29		//a strip over leather, not the whole sheet, and competes with less surface area.
30		private static final int FILL_IDLE = 0xF2241C13;
31		private static final int FILL_HOVER = 0xF2382B1B;
32		private static final int BEVEL_LIGHT = 0xFF5A4830;
33		private static final int BEVEL_DARK = 0xFF0B0906;
34		private static final int RAIL_IDLE = 0xFF6B5636;
35		private static final int RAIL_HOVER = 0xFFC9A227;
36		private static final int TEXT_IDLE = 0xFFCBBA97;
37		private static final int TEXT_HOVER = 0xFFF0E2C0;
38		private static final int TEXT_DISABLED = 0xFF6E6455;
39	
40		private static final int RAIL_WIDTH = 2;
41		/** Padding between the text and the edges, so clipped text doesn't sit flush against the bevel. */
42		private static final int TEXT_PADDING = 2;
43		private static final String ELLIPSIS = "...";
44	
45		private static final int ICON_SIZE = 14;
46		private ResourceLocation icon;
47	
48		/** A glyph at the left of the row (school, creature type...). Null = plain row. */
49		public TomeButton withIcon(ResourceLocation icon) {
50			this.icon = icon;
51			return this;
52		}
53	
54		public TomeButton(int x, int y, int width, int height, Component message, OnPress onPress) {
55			super(x, y, width, height, message, onPress, DEFAULT_NARRATION);
56		}
57	
58		/** Same entry point as {@code Button.builder(...)}, so the call site that creates it doesn't need to change shape. */
59		public static TomeButton of(Component message, OnPress onPress, int x, int y, int width, int height) {
60			return new TomeButton(x, y, width, height, message, onPress);
61		}
62	
63		@Override
64		public void renderWidget(GuiGraphics guiGraphics, int mouseX, int mouseY, float partialTick) {
65			int left = this.getX();
66			int top = this.getY();
67			int right = left + this.width;
68			int bottom = top + this.height;
69	
70			boolean active = this.isHoveredOrFocused() && this.active;
71			int alpha = Mth.ceil(this.alpha * 255.0F) << 24;
72	
73			guiGraphics.fill(left, top, right, bottom, (active ? FILL_HOVER : FILL_IDLE));
74			//Minecraft-style bevel, same as GuiStyle: it's what makes the row feel like it belongs to the game.
75			guiGraphics.fill(left, top, right - 1, top + 1, BEVEL_LIGHT);
76			guiGraphics.fill(left, top, left + 1, bottom - 1, BEVEL_LIGHT);
77			guiGraphics.fill(left + 1, bottom - 1, right, bottom, BEVEL_DARK);
78			guiGraphics.fill(right - 1, top + 1, right, bottom, BEVEL_DARK);
79	
80			//Brass rule on the left: it's the mark of "this is a tome row," and lighting up gives a
81			//second focus cue besides the background.
82			guiGraphics.fill(left + 1, top + 1, left + 1 + RAIL_WIDTH, bottom - 1, active ? RAIL_HOVER : RAIL_IDLE);
83	
84			int color = !this.active ? TEXT_DISABLED : (active ? TEXT_HOVER : TEXT_IDLE);
85			Minecraft minecraft = Minecraft.getInstance();
86			//The text is centered in the space LEFT after the rule, not the whole button: centering it on the
87			//button would leave it visibly off-center to the left.
88			int textLeft = left + 1 + RAIL_WIDTH + TEXT_PADDING;
89			if (icon != null) {
90				Icons.draw(guiGraphics, icon, textLeft, top + (this.height - ICON_SIZE) / 2, ICON_SIZE);
91				textLeft += ICON_SIZE + 3;
92			}
93			int textRight = right - TEXT_PADDING;
94			int available = textRight - textLeft;
95			Component message = this.getMessage();
96	
97			//Plain drawCenteredString doesn't clip ANYTHING: a label wider than the row —"Bandit Ambush ·
98			//Bandit x4, Bandit Captain · Deadly", and half the compendium list— overflowed on both sides and
99			//read as cut off at both ends, with neither a start nor an end.
100			if (this.isHoveredOrFocused()) {
101				//On top: vanilla's version, which clips it to the row and scrolls it side to side to the end. Only
102				//on the hovered row, because five labels sliding at once aren't readable, they're just watched.
103				renderScrollingString(guiGraphics, minecraft.font, message, textLeft, top, textRight, bottom, color | alpha);
104				return;
105			}
106			int y = top + (this.height - 8) / 2;
107			if (minecraft.font.width(message) <= available) {
108				guiGraphics.drawCenteredString(minecraft.font, message, textLeft + available / 2, y, color | alpha);
109				return;
110			}
111			//And at rest, the beginning with an ellipsis: the name is at the start, and dots signal
112			//"there's more" —which is exactly what a hard cutoff doesn't say—.
113			FormattedText trimmed = FormattedText.composite(
114				minecraft.font.substrByWidth(message, available - minecraft.font.width(ELLIPSIS)), FormattedText.of(ELLIPSIS));
115			guiGraphics.drawString(minecraft.font, Language.getInstance().getVisualOrder(trimmed),
116				textLeft, y, color | alpha);
117		}
118	}
