1	package net.hawthorn.dndsheets.client.gui;
2	
3	import net.hawthorn.dndsheets.client.gui.components.TomeButton;
4	import net.minecraft.client.gui.GuiGraphics;
5	import net.minecraft.client.gui.screens.Screen;
6	import net.minecraft.network.chat.Component;
7	
8	/**
9	 * <p>Short form: fill in a few fields and hit <b>Confirm</b> once. Adds to
10	 * {@link FormPanelScreen} the only things that are its own — the Confirm/Cancel row, the optional
11	 * Delete row, and the {@link #onConfirm()} that fires the send.</p>
12	 *
13	 * <p>The frame, the rows, the fields, and {@code tick} live in the base class: they're shared with
14	 * {@link SheetAdjustScreen}, which is a control panel (ten independent actions, no Confirm) and so
15	 * can't inherit from here no matter how much it draws the same parchment.</p>
16	 *
17	 * <p>"Cancel" (and "Confirm", once the message is sent) go back to {@code parent} instead of closing
18	 * the whole menu — same navigation mechanism as ListPickerScreen, see that class.</p>
19	 */
20	public abstract class SmallFormScreen extends FormPanelScreen {
21	
22		protected SmallFormScreen(Component title, int titleRows, Screen parent) {
23			super(title, titleRows, parent);
24		}
25	
26		/** Called when "Confirm" is pressed, before closing the screen. */
27		protected abstract void onConfirm();
28	
29		/** true adds its own "Delete" row below Confirm/Cancel — see {@link #onDelete()}. */
30		protected boolean showDeleteButton() {
31			return false;
32		}
33	
34		/** Only called if {@link #showDeleteButton()} is true; closes the screen afterward, same as onConfirm. */
35		protected void onDelete() {
36		}
37	
38		protected Component deleteButtonLabel() {
39			return Component.translatable("gui.dndsheets.common.delete");
40		}
41	
42		@Override
43		protected final void init() {
44			layoutTop();
45			buildForm();
46	
47			int y = nextRowY();
48			//TomeButton, same as ListPickerScreen's rows: the two are the mod's only button factories,
49			//so the look gets changed in two places and reaches every screen.
50			this.addRenderableWidget(TomeButton.of(Component.translatable("gui.dndsheets.common.confirm"), button -> {
51				onConfirm();
52				this.onClose();
53			}, centerX - formWidth() / 2, y, formWidth() / 2 - 2, FIELD_HEIGHT));
54	
55			this.addRenderableWidget(TomeButton.of(Component.translatable("gui.dndsheets.common.cancel"), button -> this.onClose(),
56				centerX + 2, y, formWidth() / 2 - 2, FIELD_HEIGHT));
57	
58			formBottom = y + FIELD_HEIGHT + 10;
59	
60			//Delete lives in the detail view of whatever is being edited instead of a separate row in the
61			//outer list (ManageCustomAttacksScreen/DungeonPieceListScreen/ContentEntryListScreen used to have
62			//an extra "Delete: X" row per item — it took up twice the height needed).
63			if (showDeleteButton()) {
64				int deleteY = nextRowY();
65				this.addRenderableWidget(TomeButton.of(deleteButtonLabel(), button ->
66					ConfirmScreen.ask(this.title, () -> {
67						onDelete();
68						this.onClose();
69					}), centerX - formWidth() / 2, deleteY, formWidth(), FIELD_HEIGHT));
70				formBottom = deleteY + FIELD_HEIGHT + 10;
71			}
72		}
73	
74		@Override
75		public final void render(GuiGraphics guiGraphics, int mouseX, int mouseY, float partialTicks) {
76			this.renderBackground(guiGraphics);
77			renderPanelChrome(guiGraphics);
78			super.render(guiGraphics, mouseX, mouseY, partialTicks);
79			renderFields(guiGraphics, mouseX, mouseY, partialTicks);
80		}
81	}
