2	
3	import net.hawthorn.dndsheets.client.gui.components.TomeButton;
4	import net.minecraft.client.Minecraft;
5	import net.minecraft.client.gui.GuiGraphics;
6	import net.minecraft.client.gui.components.EditBox;
7	import net.minecraft.client.gui.screens.Screen;
8	import net.minecraft.network.chat.Component;
9	import net.minecraft.world.item.Item;
10	import net.minecraft.world.item.ItemStack;
11	import net.minecraft.world.item.Items;
12	import net.minecraftforge.registries.ForgeRegistries;
13	
14	import java.util.ArrayList;
15	import java.util.LinkedHashMap;
16	import java.util.List;
17	import java.util.Locale;
18	import java.util.Map;
19	import java.util.function.Consumer;
20	import java.util.function.Predicate;
21	
22	/**
23	 * <p>Icon grid to pick a registered item (JEI-style: search, scroll, hover for the tooltip, click to choose)
24	 * instead of typing its id. Deliberately generic: it knows nothing about who asked — the caller passes what
25	 * to do with the pick ({@code onPick} gets the registry id, e.g. {@code minecraft:iron_sword}) and an
26	 * optional filter, so any screen that needs an item can reuse it.</p>
27	 *
28	 * <p>Single mode answers on the first click. Multi mode toggles items (highlighted) and answers with the
29	 * comma-separated list when "Done" is pressed; whatever the field already held that isn't a plain item id
30	 * ("minecraft:arrow x20") is kept as written while it stays selected.</p>
31	 */
32	public class ItemPickerScreen extends Screen {
33		private static final int CELL = 20;
34		private static final int TOP = 56;
35	
36		private final Screen parent;
37		private final Consumer<String> onPick;
38		private final boolean multi;
39		private final List<ItemStack> all = new ArrayList<>();
40		//id -> the text the field had for it (or the bare id), in the order they were chosen.
41		private final Map<String, String> selected = new LinkedHashMap<>();
42		private List<ItemStack> shown = new ArrayList<>();
43		private EditBox search;
44		private String lastQuery = "";
45		private int scrollRows = 0;
46		private int columns, visibleRows;
47	
48		private ItemPickerScreen(Screen parent, Predicate<Item> filter, String currentCsv, boolean multi, Consumer<String> onPick) {
49			super(Component.translatable("gui.dndsheets.item_picker.title"));
50			this.parent = parent;
51			this.onPick = onPick;
52			this.multi = multi;
53			for (Item item : ForgeRegistries.ITEMS) {
54				if (item != Items.AIR && filter.test(item)) all.add(new ItemStack(item));
55			}
56			if (multi) {
57				for (String raw : currentCsv.split(",")) {
58					String token = raw.trim();
59					if (!token.isEmpty()) selected.put(token.split("\\s+")[0], token);
60				}
61			}
62		}
63	
64		/** Single pick over the current screen; "Back"/Escape returns to it without picking. */
65		public static void open(Consumer<String> onPick) {
66			open(item -> true, "", false, onPick);
67		}
68	
69		public static void open(Predicate<Item> filter, Consumer<String> onPick) {
70			open(filter, "", false, onPick);
71		}
72	
73		/** {@code currentCsv} is what the field holds now; with {@code multi} the answer is the new comma-separated list. */
74		public static void open(Predicate<Item> filter, String currentCsv, boolean multi, Consumer<String> onPick) {
75			Minecraft minecraft = Minecraft.getInstance();
76			minecraft.setScreen(new ItemPickerScreen(minecraft.screen, filter, currentCsv, multi, onPick));
77		}
78	
79		@Override
80		protected void init() {
81			int gridWidth = Math.min(this.width - 40, CELL * 14);
82			columns = Math.max(1, gridWidth / CELL);
83			visibleRows = Math.max(1, (this.height - TOP - 24) / CELL);
84	
85			search = new EditBox(this.font, (this.width - gridWidth) / 2, 32, gridWidth, 18, Component.translatable("gui.dndsheets.common.search"));
86			search.setHint(Component.translatable("gui.dndsheets.common.search_hint"));
87			search.setValue(lastQuery);
88			search.setResponder(text -> {
89				lastQuery = text;
90				scrollRows = 0;
91				applyFilter();
92			});
93			this.addRenderableWidget(search);
94			this.setInitialFocus(search);
95			this.addRenderableWidget(TomeButton.of(Component.translatable("gui.dndsheets.common.back"), b -> this.onClose(), 8, 8, 60, 18));
96			if (multi) {
97				this.addRenderableWidget(TomeButton.of(Component.translatable("gui.dndsheets.choice.done"), b -> {
98					Minecraft.getInstance().setScreen(parent);
99					onPick.accept(String.join(", ", selected.values()));
100				}, this.width - 68, 8, 60, 18));
101			}
102			applyFilter();
103		}
104	
105		private void applyFilter() {
106			String query = lastQuery.trim().toLowerCase(Locale.ROOT);
107			shown = new ArrayList<>();
108			for (ItemStack stack : all) {
109				if (query.isEmpty()
110					|| idOf(stack).contains(query)
111					|| stack.getHoverName().getString().toLowerCase(Locale.ROOT).contains(query)) {
112					shown.add(stack);
113				}
114			}
115		}
116	
117		private static String idOf(ItemStack stack) {
118			return ForgeRegistries.ITEMS.getKey(stack.getItem()).toString();
119		}
120	
121		private int gridLeft() {
122			return (this.width - columns * CELL) / 2;
123		}
124	
125		private int maxScroll() {
126			return Math.max(0, (shown.size() + columns - 1) / columns - visibleRows);
127		}
128	
129		/** Index into {@code shown} under the mouse, or -1. */
130		private int cellAt(double mouseX, double mouseY) {
131			int col = (int) Math.floor((mouseX - gridLeft()) / CELL);
132			int row = (int) Math.floor((mouseY - TOP) / CELL);
133			if (mouseX < gridLeft() || col >= columns || mouseY < TOP || row >= visibleRows) return -1;
134			int index = (scrollRows + row) * columns + col;
135			return index < shown.size() ? index : -1;
136		}
137	
138		@Override
139		public boolean mouseClicked(double mouseX, double mouseY, int button) {
140			int index = cellAt(mouseX, mouseY);
141			if (index >= 0 && button == 0) {
142				String id = idOf(shown.get(index));
143				if (multi) {
144					if (selected.remove(id) == null) selected.put(id, id);
145				} else {
146					//Back to the caller first, then the pick: the callback usually edits a field of that screen.
147					Minecraft.getInstance().setScreen(parent);
148					onPick.accept(id);
149				}
150				return true;
151			}
152			return super.mouseClicked(mouseX, mouseY, button);
153		}
154	
155		@Override
156		public boolean mouseScrolled(double mouseX, double mouseY, double delta) {
157			scrollRows = Math.max(0, Math.min(maxScroll(), scrollRows - (int) Math.signum(delta)));
158			return true;
159		}
160	
161		@Override
162		public void tick() {
163			search.tick();
164		}
165	
166		@Override
167		public void onClose() {
168			Minecraft.getInstance().setScreen(parent);
169		}
170	
171		@Override
172		public boolean isPauseScreen() {
173			return false;
174		}
175	
176		@Override
177		public void render(GuiGraphics guiGraphics, int mouseX, int mouseY, float partialTicks) {
178			this.renderBackground(guiGraphics);
179			int left = gridLeft() - 6;
180			GuiStyle.panel(guiGraphics, left, 4, this.width - left, TOP + visibleRows * CELL + 6);
181			guiGraphics.drawCenteredString(this.font, GuiStyle.title(this.title), this.width / 2, 12, GuiStyle.TITLE_COLOR);
182	
183			int hovered = cellAt(mouseX, mouseY);
184			for (int i = 0; i < visibleRows * columns; i++) {
185				int index = scrollRows * columns + i;
186				if (index >= shown.size()) break;
187				int x = gridLeft() + (i % columns) * CELL;
