5	/**
6	 * <p>Brass frame for the character sheet's slots: the text fields and the attack list.</p>
7	 *
8	 * <p>Vanilla draws both the same way —a one-pixel gray ring (white when focused) around a
9	 * black fill— and both colors are fixed inside {@code EditBox.renderWidget} and
10	 * {@code AbstractScrollWidget.renderBorder}. On parchment that reads as widgets borrowed from another
11	 * interface.</p>
12	 *
13	 * <p>Removing the border isn't an option for {@code EditBox}: {@code setBordered(false)} takes the
14	 * black fill with it AND moves the text (from centered-with-margin to flush against the top-left
15	 * corner), and without a dark background behind it the text would have to be ink on parchment — which with
16	 * Minecraft's fixed shadow reads as doubled. So the ring isn't removed: it's repainted over. It occupies exactly
17	 * one pixel outside the slot, meaning covering it touches neither the text nor the interior.</p>
18	 *
19	 * <p>Lives in this package and not alongside {@code GuiStyle} because both sides use it: the sheet
20	 * screen ({@code client.gui}) for its fields, and {@code RollScrollWidget} (here) for the attack list and
21	 * for each row's name. {@code GuiStyle} isn't visible from here.</p>
22	 */
23	public final class TomeField {
24	
25		//Same palette as GuiStyle and TomeButton. Duplicated deliberately: the components package can't see GuiStyle,
26		//and a repeated color is less harmful than exposing the entire style class for just three integers.
27		private static final int RING = 0xFF6B5636;
28		private static final int RING_FOCUSED = 0xFFC9A227;
29		private static final int SHADOW = 0xFF8A7B5E;
30		/** Fill for a large slot (the attack list): leather, not pure black. */
31		public static final int WELL_FILL = 0xFF15100A;
32	
33		private TomeField() {
34		}
35	
36		/**
37		 * <p>Repaints a slot's ring in brass, and adds shadow outside on the top and left —where
38		 * light would come from in Minecraft's beveling— so it reads as sunken into the sheet.</p>
39		 *
40		 * <p>The coordinates are the RING's, meaning one pixel outside the widget.</p>
41		 */
42		public static void frame(GuiGraphics guiGraphics, int left, int top, int right, int bottom, boolean focused) {
43			int ring = focused ? RING_FOCUSED : RING;
44	
45			guiGraphics.fill(left, top, right, top + 1, ring);
46			guiGraphics.fill(left, bottom - 1, right, bottom, ring);
47			guiGraphics.fill(left, top, left + 1, bottom, ring);
48			guiGraphics.fill(right - 1, top, right, bottom, ring);
49	
50			guiGraphics.fill(left - 1, top - 1, right, top, SHADOW);
51			guiGraphics.fill(left - 1, top - 1, left, bottom, SHADOW);
52		}
53	
54		/** Overload for a widget: the ring sits just outside its rectangle. */
55		public static void frameWidget(GuiGraphics guiGraphics, int x, int y, int width, int height, boolean focused) {
56			frame(guiGraphics, x - 1, y - 1, x + width + 1, y + height + 1, focused);
57		}
58	}
