8	//Skeleton repeated across RestChoiceScreen/RestVoteScreen/DeathSaveScreen: a fixed-size box centered on
9	//the screen, with buttons placed at coordinates relative to that box.
10	public abstract class ModalDialogScreen extends Screen {
11		private final int dialogWidth;
12		private final int dialogHeight;
13	
14		protected ModalDialogScreen(Component title, int dialogWidth, int dialogHeight) {
15			super(title);
16			this.dialogWidth = dialogWidth;
17			this.dialogHeight = dialogHeight;
18		}
19	
20		protected int dialogLeft() {
21			return (this.width - dialogWidth) / 2;
22		}
23	
24		protected int dialogTop() {
25			return (this.height - dialogHeight) / 2;
26		}
27	
28		//First line of render() in every subclass, instead of a bare renderBackground(): draws vanilla's
29		//blurred background PLUS a bordered panel behind the dialog box (see GuiStyle), so it isn't just text
30		//and buttons floating over the world. Previously only DeathSaveScreen drew its own panel.
31		protected final void renderPanel(GuiGraphics guiGraphics) {
32			this.renderBackground(guiGraphics);
33			GuiStyle.panel(guiGraphics, dialogLeft(), dialogTop(), dialogLeft() + dialogWidth, dialogTop() + dialogHeight);
34		}
35	
36		//x/y relative to the dialog's top-left corner, same as the coordinates each screen already used by
37		//hand against its own "left"/"top".
38		protected Button addModalButton(int x, int y, int width, int height, Component message, Button.OnPress onPress) {
39			//TomeButton: the third and last place in the mod that manufactures buttons, so dialogs don't
40			//stay stuck with vanilla gray while lists and forms get the parchment look.
41			return this.addRenderableWidget(net.hawthorn.dndsheets.client.gui.components.TomeButton.of(
42				message, onPress, dialogLeft() + x, dialogTop() + y, width, height));
43		}
44	}
