65		public static void use(ServerPlayer player, TurnAction action) {
66			//Outside combat these mean nothing: no turn to spend, no opportunity attacks, no movement budget
67			//to double. Saying so is better than accepting the click and doing nothing.
68			if (!TurnManager.isActive()) {
69				player.sendSystemMessage(Component.translatable("chat.dndsheets.action.needs_combat").withStyle(ChatFormatting.GRAY));
70				return;
71			}
72			switch (action) {
73				case ACTION_SURGE -> { useActionSurge(player); return; }
74				case FLURRY_OF_BLOWS -> { useFlurry(player); return; }
75				case PATIENT_DEFENSE -> { useKi(player, TurnAction.DODGE); return; }
76				case STEP_DASH -> { useKi(player, TurnAction.DASH); return; }
77				case STEP_DISENGAGE -> { useKi(player, TurnAction.DISENGAGE); return; }
78				default -> { }
79			}
80			//They ARE the turn's action, same as attacking: checked with the same tryAct, so using one also
81			//ends the turn on its own and you can't dodge AND attack in the same round.
82			if (!TurnManager.tryAct(player)) {
83				TurnManager.notifyCantAct(player);
84				return;
85			}
86	
87			if (action == TurnAction.SEARCH) { search(player); return; }
88			if (action == TurnAction.HIDE) { hide(player); return; }
89	
90			active.computeIfAbsent(player.getId(), id -> EnumSet.noneOf(TurnAction.class)).add(action);
91			CombatFx.activate(player);
92			String name = SheetLoader.characterNameOf(SheetLoader.getServerSheet(player.getStringUUID()), player);
93			ChatFeedback.broadcast(player, Component.translatable(messageKeyOf(action), name).withStyle(ChatFeedback.RESOURCE));
94		}
