422		public static boolean tryAct(Entity actor) {
423			//Before anything turn-mode related, and also outside combat: an incapacitating condition
424			//(paralyzed, stunned, petrified, unconscious) prevents acting even with no initiative active.
425			//Here, and not in every caller, because EVERY attack route — melee, projectile, PvP, spell —
426			//already passes through this exact point.
427			if (isIncapacitated(actor)) return false;
428			if (!active) return true;
429			TurnEntry currentEntry = current();
430			if (currentEntry == null || currentEntry.entityId() != actor.getId()) {
431				//A readied action: act once out of turn, spending the reaction (see TurnActionManager.releaseReadied).
432				return TurnActionManager.releaseReadied(actor);
433			}
434			boolean acted = actedThisTurn.add(actor.getId());
435			if (!acted && consumeExtraAction(actor.getId())) acted = true; //Action Surge / Flurry: an extra action of the turn.
436			//As soon as the action is spent, the turn ends on its own: nobody has to type /dndturns next.
437			//Deferred by one tick so the chat/HUD for the attack that just happened shows before "X's turn".
438			//With Action Surge still armed, the first action does NOT end it: the second one is coming.
439			if (acted && actor.level() instanceof ServerLevel level) {
440				broadcastTurnState(level);
441				if (!extraActions.containsKey(actor.getId())) scheduleAutoAdvance(level, actor.getId());
442			}
443			return acted;
444		}
